public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Start year Y and position N must be positive integers.");
    }

    int count = 0;
    for (int year = Y; true; year++) {
        // Check for potential overflow
        if (year < 0) {
            throw new RuntimeException("Year integer overflowed while searching for the Nth leap year.");
        }

        if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
            count++;
            if (count == N) {
                return year;
            }
        }
    }
}

