public static int calculateTimeNeeded(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of people cannot be negative");
    }
    // For N less than 3, no time is required as reversal is trivial or impossible.
    if (N <= 3) {
        return 0;
    }
    // The pattern observed from the examples is that the required time equals
    // two minutes per person beyond the initial 3 people.
    int timeNeeded = 2 * (N - 3);
    return timeNeeded;
}

