public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Skip empty strings, they cannot contribute to any substring of positive length
    // but they still impose the requirement that X or its reverse must be found in them.
    // An empty string can only match X or its reverse if X is also empty; hence the
    // largest valid substring length cannot be positive if any given string is empty.
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }

    String first = strings.get(0);
    int maxLen = first.length();

    // Utility to reverse a string
    java.util.function.Function<String, String> reverse = (String t) -> new StringBuilder(t).reverse().toString();

    // Iterate lengths from longest to shortest
    for (int len = maxLen; len >= 1; len--) {
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (int start = 0; start <= first.length() - len; start++) {
            String sub = first.substring(start, start + len);
            candidates.add(sub);
            // Also consider its reverse as a candidate
            String rev = reverse.apply(sub);
            candidates.add(rev);
        }
        // Check each candidate against all strings
        for (String cand : candidates) {
            boolean ok = true;
            for (String s : strings) {
                if (!s.contains(cand) && !s.contains(reverse.apply(cand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

