    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0; // empty string cannot contain any non-empty substring
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    // Find the string with minimal length to generate candidates
