public static int maxRegions(int N) {
    // Handle non-positive input: no triangles means the whole plane is one region.
    if (N <= 0) {
        return 1;
    }
    // Compute using the derived formula: 3 * N * (N - 1) + 2
    // Use long for intermediate calculation to avoid overflow before casting back to int.
    long result = 3L * N * (N - 1L) + 2L;
    // If result exceeds Integer.MAX_VALUE, clamp to that value
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    return (int) result;
}

