public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        return 0;
    }
    // Build a set of all numbers for O(1) lookups
    java.util.HashSet<Integer> allNumbers = new java.util.HashSet<>();
    for (int num : numbers) {
        allNumbers.add(num);
    }

    int count = 0;
    for (int num : numbers) {
        if ((num & 1) == 0) { // num is even
            int half = num / 2;
            if (allNumbers.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

