public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    // Build frequency map
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0) {
            int half = n / 2;
            if (half == n) { // only possible for n == 0
                if (freq.get(half) >= 2) {
                    count++;
                }
            } else {
                if (freq.containsKey(half)) {
                    count++;
                }
            }
        }
    }
    return count;
}

