public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < start.length && i < end.length; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int v : coord) {
            sb.append(v).append('#');
        }
        return sb.toString();
    };

    // Build adjacency list
    java.util.Map<String, java.util.Set<String>> graph = new java.util.HashMap<>();
    java.util.Set<String> allNodes = new java.util.HashSet<>();
    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);
    allNodes.add(startKey);
    allNodes.add(endKey);

    for (int[] path : paths) {
        // Skip invalid paths
        if (path == null || path.length != start.length * 2) {
            continue;
        }
        int[] a = new int[start.length];
        int[] b = new int[start.length];
        System.arraycopy(path, 0, a, 0, start.length);
        System.arraycopy(path, start.length, b, 0, start.length);
        String aKey = coordKey.apply(a);
        String bKey = coordKey.apply(b);
        allNodes.add(aKey);
        allNodes.add(bKey);
        graph.computeIfAbsent(aKey, k -> new java.util.HashSet<>()).add(bKey);
        graph.computeIfAbsent(bKey, k -> new java.util.HashSet<>()).add(aKey); // Assuming undirected adjacency
    }

    // BFS to check reachability
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.Set<String> neighbors = graph.getOrDefault(cur, java.util.Collections.emptySet());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

