public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) throw new IllegalArgumentException("Grid size must be positive");
        if (start == null || start.length != 2) throw new IllegalArgumentException("Invalid start coordinates");
        if (end == null || end.length != 2) throw new IllegalArgumentException("Invalid end coordinates");

        if (!within(start, n) || !within(end, n))
            throw new IllegalArgumentException("Start or end coordinates out of bounds");

        if (start[0] == end[0] && start[1] == end[1]) return "can be travelled";

        java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

        if (paths != null) {
            for (int i = 0; i < paths.length; i++) {
                int[] p = paths[i];
                if (p == null || p.length != 4)
                    throw new IllegalArgumentException("Invalid path at index " + i);
                int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
                if (!within(new int[]{x1, y1}, n) || !within(new int[]{x2, y2}, n))
                    throw new IllegalArgumentException("Path coordinates out of bounds at index " + i);
                if (!areAdjacent(x1, y1, x2, y2))
                    throw new IllegalArgumentException("Path not between adjacent intersections at index " + i);

                String a = coordKey(x1, y1);
                String b = coordKey(x2, y2);
                adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
                adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
            }
        }

        java.util.Queue<String> queue = new java.util.LinkedList<>();
        java.util.Set<String> visited = new java.util.HashSet<>();

        String startKey = coordKey(start[0], start[1]);
        String endKey = coordKey(end[0], end[1]);

        queue.offer(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            for (String nb : adj.getOrDefault(cur, java.util.Collections.emptyList())) {
                if (!visited.contains(nb)) {
                    if (nb.equals(endKey)) return "can be travelled";
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }
        return "cannot be travelled";
    } catch (IllegalArgumentException e) {
        throw e;
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

