public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) return "cannot be travelled";
    if (start == null || end == null || start.length != 2 || end.length != 2) return "cannot be travelled";
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n) return "cannot be travelled";
    if (ex < 0 || ex >= n || ey < 0 || ey >= n) return "cannot be travelled";

    // Mapping from a node id to its neighbors
    Map<Integer, List<Integer>> adj = new HashMap<>();

    // Helper to convert coordinates to node id
    java.util.function.IntUnaryOperator toId = (coord) -> coord[0] * n + coord[1];

    for (int[] path : paths) {
        if (path == null) continue;
        if (path.length == 4) {
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
            int id1 = x1 * n + y1;
            int id2 = x2 * n + y2;
            adj.computeIfAbsent(id1, k -> new java.util.ArrayList<>()).add(id2);
            adj.computeIfAbsent(id2, k -> new java.util.ArrayList<>()).add(id1);
        } else if (path.length == 2) {
            // Interpret as two node ids (already flattened)
            int id1 = path[0];
            int id2 = path[1];
            if (id1 < 0 || id1 >= n * n || id2 < 0 || id2 >= n * n) continue;
            adj.computeIfAbsent(id1, k -> new java.util.ArrayList<>()).add(id2);
            adj.computeIfAbsent(id2, k -> new java.util.ArrayList<>()).add(id1);
        } else {
            // Unsupported format; ignore this entry
            continue;
        }
    }

    int startId = sx * n + sy;
    int endId = ex * n + ey;

    // BFS
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.offer(startId);
    visited.add(startId);

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endId) return "can be travelled";
        List<Integer> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (int nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

