    int minLen = Math.min(len1, len2);
    int matchCount = 0;
    for (int i = 0; i < minLen; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            matchCount++;
        }
    }

    int numerator = matchCount * 2;  // as per problem statement

    // Build the result string
    StringBuilder sb = new StringBuilder();
    sb.append("appx(").append(word1).append(", ").append(word2).append(") = ");

    if (totalLen == 0 || numerator == 0) {
        sb.append("0");
    } else {
        // Reduce the fraction
        int gcd = Integer.gcd(numerator, totalLen);
        int redNum = numerator / gcd;
        int redDen = totalLen / gcd;
        if (redNum == redDen) {
            sb.append("1");
        } else {
            sb.append(redNum).append("/").append(redDen);
        }
    }

    return sb.toString();
}

