public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    java.util.List<Integer>[] adj = new java.util.List[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        adj[u].add(v);
        adj[v].add(u);
    }

    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 indicates unvisited
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    java.util.ArrayDeque<Integer> order = new java.util.ArrayDeque<>();

    int root = 0;
    stack.push(root);
    parent[root] = -1;

    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.push(node); // store reverse post-order
        for (int neighbor : adj[node]) {
            if (parent[neighbor] == -2) {
                parent[neighbor] = node;
                stack.push(neighbor);
            }
        }
    }

    int ans = 0;
    boolean[] subtreeHasApple = new boolean[n];
    System.arraycopy(hasApple, 0, subtreeHasApple, 0, n);

    while (!order.isEmpty()) {
        int node = order.pop();
        for (int neighbor : adj[node]) {
            if (parent[neighbor] == node) { // neighbor is child
                if (subtreeHasApple[neighbor]) {
                    ans += 2;
                    subtreeHasApple[node] = true;
                }
            }
        }
    }

    return ans;
}

