public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int v : nums) total += v;
    int mid = n / 2;
    int leftSize = mid;
    int rightSize = n - mid;
    // Map from subset size to set of subset sums for left half
    Map<Integer, Set<Long>> leftMap = new HashMap<>();
    for (int mask = 1; mask < (1 << leftSize); mask++) {
        long sum = 0;
        int cnt = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask >> i & 1) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        leftMap.computeIfAbsent(cnt, k -> new HashSet<>()).add(sum);
    }
    // Same for right half
    Map<Integer, Set<Long>> rightMap = new HashMap<>();
    for (int mask = 1; mask < (1 << rightSize); mask++) {
        long sum = 0;
        int cnt = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask >> i & 1) != 0) {
                sum += nums[mid + i];
                cnt++;
            }
        }
        rightMap.computeIfAbsent(cnt, k -> new HashSet<>()).add(sum);
    }
    // Try each possible subset size k (1 … n-1)
    for (int k = 1; k <= n - 1; k++) {
        if ((total * k) % n != 0) continue;
        long target = (long) total * k / n;
        // Subset entirely in left or right
        Set<Long> leftSet = leftMap.get(k);
        if (leftSet != null && leftSet.contains(target)) return true;
        Set<Long> rightSet = rightMap.get(k);
        if (rightSet != null && rightSet.contains(target)) return true;
        // Combine subsets from both halves
        for (int k1 = 1; k1 <= Math.min(k - 1, leftSize); k1++) {
