public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int stepFromOne = dp[i - 1] + cost[i - 1];
        int stepFromTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(stepFromOne, stepFromTwo);
    }
    return dp[n];
}

