public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    long totalCodes = 1L << k;
    // Quick impossibility check: the number of substrings of length k is at least totalCodes
    if (n < k || n - k + 1 < totalCodes) {
        return false;
    }

    // For small k we can use a boolean array for faster lookup
    if (k <= 20) {
        int size = 1 << k;
        boolean[] seen = new boolean[size];
        int mask = size - 1;
        int curr = 0;
        for (int i = 0; i < n; i++) {
            curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                if (!seen[curr]) {
                    seen[curr] = true;
                    size--; // decrease count of unseen codes
                    if (size == totalCodes - (n - k + 1)) {
                        // All codes have been seen
                        return true;
                    }
                }
            }
        }
        // Check if all codes were seen
        for (boolean b : seen) {
            if (!b) {
                return false;
            }
        }
        return true;
    } else {
        // For larger k use a Set to avoid integer overflow in the mask
        java.util.Set<Long> seen = new java.util.HashSet<>();
        long mask = totalCodes - 1;
        long curr = 0L;
        for (int i = 0; i < n; i++) {
            curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(curr);
                if (seen.size() == totalCodes) {
                    return true;
                }
            }
        }
        return seen.size() == totalCodes;
    }
}

