public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    if (n % 2 == 0) {
        int half = n / 2;
        return half * half; // (n/2)^2
    } else {
        int a = (n - 1) / 2;
        int b = (n + 1) / 2;
        return a * b; // ((n-1)/2) * ((n+1)/2)
    }
}

