public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient for k <= 1e9
    int len = 0;
    fib[len++] = 1; // F1
    fib[len++] = 1; // F2
    while (true) {
        int next = fib[len - 1] + fib[len - 2];
        if (next > k) {
            break;
        }
        fib[len++] = next;
    }
    // Greedy selection of largest Fibonacci numbers
    int count = 0;
    int remaining = k;
    for (int i = len - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

