public static int addDigits(int num) {
    // Handle non-negative integers only; if negative, return 0 (or could throw exception)
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

