public static int longestLine(int[][] mat) {
    // Handle null or empty matrix
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    // dp[i][j][k]: longest line ending at (i, j) in direction k
    // 0: horizontal (left), 1: vertical (up), 2: diagonal (up-left), 3: anti-diagonal (up-right)
    int[][][] dp = new int[rows][cols][4];
    int maxLen = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                dp[i][j][3] = (i > 0 && j < cols - 1) ? dp[i - 1][j + 1][3] + 1 : 1;
                int cellMax = Math.max(
                        Math.max(dp[i][j][0], dp[i][j][1]),
                        Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                dp[i][j][0] = dp[i][j][1] = dp[i][j][2] = dp[i][j][3] = 0;
            }
        }
    }
    return maxLen;
}

