public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Find maximum possible sum to precompute perfect squares
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int k = 0; k * k <= maxSum; k++) {
        isSquare[k * k] = true;
    }
    // Sort array to handle duplicates
    java.util.Arrays.sort(A);
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    // Initialize dp for masks with a single element
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // Build DP over increasing mask sizes
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            // Try to append an unused element j
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue; // already used
                // Skip duplicate values to avoid counting same permutations
                if (j > 0 && A[j] == A[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                if (isSquare[A[last] + A[j]]) {
                    dp[mask | (1 << j)][j] += cur;
                }
            }
        }
    }
    long total = 0;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }
    return (int) total;
}

