public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int s = arr[i] + arr[j];
            int r = (int) Math.sqrt(s);
            can[i][j] = r * r == s;
        }
    }
    int maxMask = 1 << n;
    long[][] memo = new long[maxMask][n + 1];
    for (int i = 0; i < maxMask; i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }
    class Solver {
        long dfs(int mask, int last) {
            if (mask == (maxMask - 1)) return 1;
            long val = memo[mask][last + 1];
            if (val != -1) return val;
            long res = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (last != -1 && !can[last][i]) continue;
                if (i > 0 && arr[i] == arr[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                res += dfs(mask | (1 << i), i);
            }
            memo[mask][last + 1] = res;
            return res;
        }
    }
    Solver solver = new Solver();
    return (int) solver.dfs(0, -1);
}

