public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Step 1: Find the largest index i such that digits[i] < digits[i + 1]
    int i = length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Digits are in non-increasing order; no larger permutation exists
        return -1;
    }

    // Step 2: Find the largest index j > i such that digits[j] > digits[i]
    int j = length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the subarray from i+1 to the end
    int left = i + 1;
    int right = length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    try {
        long value = Long.parseLong(new String(digits));
        if (value > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) value;
    } catch (NumberFormatException e) {
        // Should not occur, but return -1 for safety
        return -1;
    }
}

