    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {
        {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}
    };
    char[] temp = new char[n];
    java.util.function.BiConsumer<Integer, Integer> backtrack = null;
    backtrack = (left, right) -> {
        if (left > right) {
            result.add(new String(temp));
            return;
        }
        if (left == right) {
            for (char c : new char[]{'0', '1', '8'}) {
                temp[left] = c;
