        for (char[] pair : pairs) {
            if (left == 0 && pair[0] == '0' && n > 1) {
                continue; // leading zero not allowed for length > 1
            }
            temp[left] = pair[0];
            temp[right] = pair[1];
            backtrack.accept(left + 1, right - 1);
        }
    };
    backtrack.accept(0, n - 1);
    return result;
}

