public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for null subarrays
    for (int[] point : points) {
        if (point == null || point.length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    int[] p0 = points[0], p1 = points[1], p2 = points[2];
    if ((p0[0] == p1[0] && p0[1] == p1[1]) ||
        (p0[0] == p2[0] && p0[1] == p2[1]) ||
        (p1[0] == p2[0] && p1[1] == p2[1])) {
        return false;
    }
    // Check collinearity using area method
    int area = (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0]);
    return area != 0;
}

