    // Validate input: must be non-null and contain exactly three points
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        // Extract the coordinates
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];

        // Check that all points are distinct
        if ((x1 == x2 && y1 == y2) || (x1 == x3 && y1 == y3) || (x2 == x3 && y2 == y3)) {
            return false;
        }

        // Compute twice the area of the triangle (should not be zero for a valid boomerang)
        int value = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
        return value != 0;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, treat as not a boomerang
        return false;
    }
}

