public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // If n is a perfect square, return 1
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }

    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        int sqrtR = (int) Math.sqrt(remainder);
        if (sqrtR * sqrtR == remainder) {
            return 2;
        }
    }

    // Legendre's three-square theorem check
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }

    // Otherwise, the answer is 3
    return 3;
}

